import { ExhibitController } from './solution';
import type { Exhibit, ExhibitEvents } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsRangeError(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { if (error instanceof RangeError) return; throw new Error(`${message}: wrong error`); }
  throw new Error(`${message}: did not throw`);
}

for (const rating of [-1, 5.0001, Number.NaN, Infinity, -Infinity]) {
  throwsRangeError(() => new ExhibitController('k', 'c', 'a', rating), `constructor rating ${String(rating)}`);
}
new ExhibitController('low', '', '', 0);
new ExhibitController('high', '', '', 5);

const controller = new ExhibitController('original', 'caption', 'art', 2);
equal(controller.key, 'original', 'key');
equal(controller.caption, 'caption', 'caption');
equal(controller.artwork, 'art', 'artwork');
equal(controller.rating, 2, 'rating');
const stateA = controller.state;
const stateB = controller.state;
assert(stateA !== stateB, 'state must be fresh');

const events: string[] = [];
controller.on('captionChanged', value => events.push(`caption:${value}`));
controller.on('artworkChanged', value => events.push(`artwork:${value}`));
controller.on('ratingChanged', value => events.push(`rating:${value}`));
controller.caption = 'caption';
controller.artwork = 'art';
controller.rating = 2;
equal(events.length, 0, 'unchanged setters emit nothing');
controller.caption = 'new caption';
controller.artwork = 'new art';
controller.rating = 5;
equal(events.join('|'), 'caption:new caption|artwork:new art|rating:5', 'setter events');
throwsRangeError(() => { controller.rating = 6; }, 'invalid setter rating');
equal(controller.rating, 5, 'invalid setter does not change rating');

const next: Exhibit = { key: 'replacement', caption: 'updated', artwork: 'updated art', rating: 3 };
events.length = 0;
controller.update(next);
equal(controller.key, 'original', 'update preserves original key');
equal(controller.caption, 'updated', 'update caption');
equal(controller.artwork, 'updated art', 'update artwork');
equal(controller.rating, 3, 'update rating');
equal(events.join('|'), 'caption:updated|artwork:updated art|rating:3', 'update event order');
equal(next.key, 'replacement', 'update input not mutated');

const beforeInvalid = controller.state;
throwsRangeError(() => controller.update({ key: 'x', caption: 'should not apply', artwork: 'no', rating: Number.NaN }), 'invalid update rating');
equal(JSON.stringify(controller.state), JSON.stringify(beforeInvalid), 'invalid update is atomic');

const orderController = new ExhibitController('k', 'c', 'a', 1);
const order: string[] = [];
let removeSecond = () => {};
orderController.on('captionChanged', () => {
  order.push('first');
  removeSecond();
});
removeSecond = orderController.on('captionChanged', () => order.push('second'));
const duplicate = () => order.push('duplicate');
const removeDuplicateA = orderController.on('captionChanged', duplicate);
orderController.on('captionChanged', duplicate);
orderController.caption = 'one';
equal(order.join(','), 'first,second,duplicate,duplicate', 'snapshot and registration order');
order.length = 0;
removeSecond();
removeSecond();
removeDuplicateA();
removeDuplicateA();
orderController.caption = 'two';
equal(order.join(','), 'first,duplicate', 'idempotent unsubscribe and separate duplicates');

const eventName: keyof ExhibitEvents = 'ratingChanged';
equal(eventName, 'ratingChanged', 'ExhibitEvents export');

