    this.emit('artworkChanged', value);
  }

  public set rating(value: number) {
    this.assertRating(value);
    if (value === this._rating) return;
    this._rating = value;
    this.emit('ratingChanged', value);
  }

  public get state(): Exhibit {
    return { key: this._key, caption: this._caption, artwork: this._artwork, rating: this._rating };
  }

  public update(next: Exhibit): void {
    this.assertRating(next.rating);
    this.caption = next.caption;
    this.artwork = next.artwork;
    this.rating = next.rating;
  }

  public on<K extends keyof ExhibitEvents>(event: K, listener: (value: ExhibitEvents[K]) => void): () => void {
    const bucket = this.listeners[event] as Array<(value: ExhibitEvents[K]) => void>;
    bucket.push(listener);
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      const index = bucket.indexOf(listener);
      if (index >= 0) bucket.splice(index, 1);
    };
  }

  private emit<K extends keyof ExhibitEvents>(event: K, value: ExhibitEvents[K]): void {
    const snapshot = [...this.listeners[event]] as Array<(item: ExhibitEvents[K]) => void>;
    for (const listener of snapshot) listener(value);
  }

  private assertRating(value: number): void {
    if (!Number.isFinite(value) || value < 0 || value > 5) {
      throw new RangeError('rating must be between 0 and 5');
    }
  }
}
